import { Check } from 'lucide-react'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card'
import { Section, SectionHeading, type HeadingLevel } from '@/components/ds/blocks/section'

export type Plan = {
  name: string
  price: string
  /** Rendered after the price, e.g. " / month". Omit for a one-off figure. */
  period?: string
  body?: string
  features: string[]
  cta: string
  /** Lifts the plan with a primary border and a filled button. */
  featured?: boolean
  /** Overrides the "Popular" badge on the featured plan. */
  badge?: string
}

export type Pricing01Props = {
  eyebrow?: string
  title?: string
  description?: string
  plans: Plan[]
  /** Heading level for the section title. See `HeadingLevel`. */
  headingLevel?: HeadingLevel
}

/**
 * A three-up plan comparison.
 *
 * Every plan is a prop, including the price and the call to action. It previously
 * hardcoded "$0 / $24 / $68", "Talk to us", "MIT licence" and "Figma library",
 * and shipped a heading reading "Pricing" above a title already reading "Pick a
 * plan". A shared library has no plans to sell, so those strings described a
 * business that does not exist here, and every consumer who installed the block
 * inherited them.
 */
export function Pricing01({
  eyebrow,
  title,
  description,
  plans,
  headingLevel = 'h2',
}: Pricing01Props) {
  return (
    <Section>
      {title ? (
        <SectionHeading
          as={headingLevel}
          eyebrow={eyebrow}
          title={title}
          description={description}
          className="mb-12"
        />
      ) : null}

      <div className="grid gap-6 lg:grid-cols-3">
        {plans.map((plan) => (
          <Card
            key={plan.name}
            className={plan.featured ? 'border-primary shadow-md' : undefined}
          >
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>{plan.name}</CardTitle>
                {plan.featured ? <Badge>{plan.badge ?? 'Popular'}</Badge> : null}
              </div>
              {plan.body ? <CardDescription>{plan.body}</CardDescription> : null}
              <p className="mt-2 text-3xl font-semibold tracking-tight">
                {plan.price}
                {plan.period ? (
                  <span className="text-muted-foreground text-sm font-normal">
                    {plan.period}
                  </span>
                ) : null}
              </p>
            </CardHeader>

            <CardContent className="flex flex-col gap-3">
              {/*
                Keyed by position, not by the feature string. The string is display
                content rather than identity, and a plan is free to list the same
                line twice; keying on it logged React's duplicate-key error and let
                React drop and reorder rows. `key={index}` is correct here because
                this list is static: it is rendered once from props and never
                reordered, filtered or appended to, so there is no state to
                preserve across a reorder that a positional key could lose.
              */}
              {plan.features.map((feature, index) => (
                <p key={index} className="flex items-start gap-2 text-sm">
                  <Check className="text-success mt-0.5 size-4 shrink-0" />
                  {feature}
                </p>
              ))}
            </CardContent>

            <CardFooter className="mt-auto">
              <Button
                className="w-full"
                variant={plan.featured ? 'default' : 'outline'}
              >
                {plan.cta}
              </Button>
            </CardFooter>
          </Card>
        ))}
      </div>
    </Section>
  )
}

export default Pricing01

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

/**
 * Container primitive. Every block composes its own section from this so vertical
 * rhythm stays consistent across the catalog instead of being re-invented per block.
 */
export function Section({
  className,
  children,
  ...props
}: React.ComponentProps<'section'>) {
  return (
    <section
      className={cn('py-16 sm:py-24', className)}
      {...props}
    >
      <div className="mx-auto w-full max-w-6xl px-6 lg:px-8">
        {children}
      </div>
    </section>
  )
}

/**
 * The six heading levels a block can be composed at.
 *
 * Every block takes a `headingLevel` prop typed with this and forwards it to the
 * one heading it renders, so the surrounding document decides where the block
 * sits in the outline rather than the block deciding for itself. `h2` is the
 * default because a block is composed, not a page.
 *
 * A block rendered where the document *already* owns a heading for the same
 * content passes one level deeper. A catalog card already names the block in its
 * own `h2`, so the copy of the block embedded inside that card passes `h3`: the
 * embedded heading then reads as a child of the card that introduces it instead
 * of as a second, competing sibling. This is a fact about where the block was
 * placed, not about the block, which is why it is a prop and not a default.
 */
export type HeadingLevel = 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'

export function SectionHeading({
  eyebrow,
  title,
  as: Heading = 'h2',
  description,
  align = 'center',
  className,
}: {
  eyebrow?: ReactNode
  title: ReactNode
  description?: ReactNode
  align?: 'center' | 'left'
  /**
   * Heading level. Defaults to `h2` because blocks compose under a page heading.
   * A page that renders a block as its primary heading passes `as="h1"` — a
   * document with no `h1` gives screen-reader and search engines no top-level
   * entry point.
   */
  as?: HeadingLevel
  className?: string
}) {
  return (
    <div
      className={cn(
        'flex flex-col gap-4',
        align === 'center' ? 'items-center text-center' : 'items-start text-left',
        className,
      )}
    >
      {eyebrow ? (
        <span className="text-muted-foreground text-sm font-medium tracking-wide uppercase">
          {eyebrow}
        </span>
      ) : null}
      <Heading className="text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
        {title}
      </Heading>
      {description ? (
        <p className="text-muted-foreground max-w-2xl text-lg text-pretty">
          {description}
        </p>
      ) : null}
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
